import type { MeaningPack } from '../../types';

/** Harikathamrutasara sandhis 3–10: meanings (en). */
export const enHks1: MeaningPack = {
  lang: 'en',
  texts: {
    'harikathamrutasara-03': {
      verses: {
        '0.0': "With the grace of the guru, I will tell the essence of the nectar of Hari's stories; devout devotees of the Lord, listen to it with respect. (The refrain sung at the start of every sandhi.)",
      },
    },
    'harikathamrutasara-04': {
      summary: "Sandhi 4 (Bhojana-rasa-vibhaga, \"the division of tastes in food\"): Hari is present in the food that every being eats and in its tastes, in many forms (Vasudeva, Sankarshana, Pradyumna, Aniruddha, Narayana), whose numbers the sandhi counts out. One who eats knowing this, offering the meal to Him, is as one who performs the great daily sacrifices; Hari accepts a devotee's offering with love and is never affected by what He eats.",
      verses: {
        '0.0': "With the grace of the guru, I will tell the essence of the nectar of Hari's stories; devout devotees of the Lord, listen to it with respect. (The refrain sung at the start of every sandhi.)",
        '0.1': "All beings in the egg of Brahma eat the four kinds of food, and Hari, present in them as the four kinds of taste, makes each eat what the mind wants. He gives growth to the body, delight to the senses, and to the gods the joy of seeing Him.",
        '0.2': "The gross body is like a nest for the soul (linga). Hari divides the essence of the food into sixteen parts and gives growth to the body's sixteen parts (kalas); as Kroda, the Boar, He moves in bliss within the deities of the 72,000 channels (nadis) and makes the body move in the world.",
        '0.3': "Hari, denoted by the word 'water', dwells in water as the six tastes. Taking the shape of the channels, He is present in the 36,000 male channels (on the right, called 'day') and the 36,000 female channels (on the left, called 'night'), and plays in every body under the fair name Brihati.",
        '0.4': "The six tastes, divided by sattva, rajas and tamas, become eighteen; they are essential or not, mixed with one another, one prominent and the rest faint, separate or blended, and full of conscious power. Knowing that Lakshmi's Lord is present in the body and in every good food in 72,000 forms called rasa, eat with that understanding.",
        '0.5': "The forms of Hari as the taste in milk number 354; in ghee, 29; in good jaggery, 5,101; and in fruits, 2,825 (two thousand, 'six and two' = eight hundred, and twenty-five, as the commentary reckons it).",
        '0.6': "In the clear, firm, sharp and other tastes Hari is present in 8,309 forms ('three and five' thousand, three hundred and nine); one should eat meditating on them. Within Vayu and the lords of the principles He is called by these names; to the wise who contemplate Him thus, He shines in the mind.",
        '0.7': "As Kapila, Narasimha and Parashurama in the eyes, nose and mouth; as the Fish (Matsya) in the tongue, as Hamsa in the teeth, as Hayagriva in speech (the three-footed Gayatri and verse): ever full of boundless bliss, Hari dwells even in the poor and weak and accepts and gives to each the taste that is theirs.",
        '0.8': "Hari, of incomparable bliss, is within the enjoyers as their power, in the forms of Sankarshana and Pradyumna; in the food as the one who satisfies, under the two names Narayana and Aniruddha, He gives contentment to the living being.",
        '0.9': "Vasudeva gives room within and without as the one present in space (Nabhastha), and in five forms plays with Rama (Lakshmi). One who knows that He is within the whole multitude of beings, from Brahma, Shiva and Indra down, is the one who truly knows.",
        '0.10': "Vasudeva is in the rice and the various good dishes; Sankarshana is in the sweet rice, Aniruddha in the ghee; Hari who rides Garuda is in the dal soup, and Indra's younger brother (Upendra) in the vegetables: thus the root Lord Narayana is present in everything.",
        '0.11': "Within the countless good foods He is whole in each, yet through His infinite parts He is spoken of as divided; He satisfies the beings of the world and has no inner difference. Knowing both these aspects of Him, eat and feed others, offering the food to Him.",
        '0.12': "One who eats knowing this is ever fasting, free from illness and sin, and has performed the great sacrifices daily. Think: all that goes, stays and comes rests on Rama's Lord. The ocean of mercy listens to such a devotee's words as He listens to Lakshmi, the mother of the world.",
        '0.13': "Aniruddha, the enjoyer of the essence, is called Annamaya (the food-sheath) in 8,251 forms ('six and two' thousand, two hundred and fifty-one); Pradyumna appears in the world as Pranamaya (the breath-sheath) in 5,543 forms ('three and two and a half' thousand, five hundred and forty-three).",
        '0.14': "Within and beyond those two sheaths, Sankarshana takes 5,62,107 forms and is called Manomaya (the mind-sheath), far from every flaw; and (continuing into the next verse) Vasudeva in 4,374 forms ...",
        '0.15': "Vasudeva, in 4,374 forms, is called Vijnanamaya (the knowledge-sheath) and pervades the great principle (mahat) and the other tattvas along with their presiding lords. Lakshmi (Rama) too destroys the subtle and gross bodies of those who have attained direct realization (aparoksha) of Brahman, thereby liberating them.",
        '0.16': "Narayana takes 5,125 forms and is called Anandamaya (the bliss-sheath) day by day; in 5,85,400 forms He fills the egg of Brahma, which has five sheaths.",
        '0.17': "Aniruddha, Shanti's Lord, is the food (anna) in 101 forms; Pradyumna, called Prana, appears in 513 forms; Sankarshana is in the mind, with its changes, in 55 forms; and as the knowing self (vijnana), named Vishva, He is in 584 forms.",
        '0.18': "Taking 3,052 forms, the one called Narayana is Anandamaya within the body. In all, in these 4,305 forms (101 + 513 + 55 + 584 + 3,052) He dwells within Vayu, Bharati's Lord, like ghee within butter.",
        '0.19': "In the prana breath within the body Aniruddha is present in 53 forms; in the apana breath Pradyumna in 511; in the third, the vyana breath, Sankarshana in 55 ('five and half a hundred'); and in the udana breath the Lord of Maya (Vasudeva) in 535 forms.",
        '0.20': "The root Narayana, Lord of all, takes 557 forms and is present everywhere in the samana breath. In sport He guards the worlds within the five vital breaths in 1,711 forms in all (53 + 511 + 55 + 535 + 557).",
        '0.21': "Aniruddha, in 93 forms (in the 31 ancestral deities of the body, eight Vasus, eleven Rudras and twelve Adityas, each with its three ego-principles), is ever the master of the rite. He becomes the food for Agni, Yama, Soma and the other ancestral deities; as Pradyumna He divides the merit into the gods' share and the ancestors' share, as Sankarshana He makes nine portions, and as the Fourth (Turya, Vasudeva) He feeds them to the ancestors, giving the meal of eternal bliss.",
        '0.22': "Named after the ninety-six shraddha days of the year (Shannavati), the Lord, standing within the Vasus, the three-eyed Rudras and the Suns (Adityas), accepts the pious acts that devotees who have taken refuge in Him perform each day with sincere devotion; that ocean of mercy gives the ancestors immeasurable happiness and protects the doers at all times.",
        '0.23': "Sutapa (the protector of all beings, His children), present in the fifty-one letters, in the senses, in the twenty-four principles and in the body's constituents, Aniruddha ceaselessly tends the multitudes of souls in the world. Those who know worship these four-fold forms named 'ninety-six' (51 letter-forms + 11 in the senses + 24 in the principles + 7 in the constituents + 3 in the qualities, as the commentary counts them).",
        '0.24': "He who holds the whole universe in His belly ate Shabari's chewed fruit in the forest, pleased the cowherd women of Gokula, ate the rice the sages' wives gave, and was pleased with Kubja's perfume. Served by hosts of sages and gods, will He refuse the fruit of action that we offer Him?",
        '0.25': "The happiness of Lakshmi, Brahma, Indra and the others is not equal to even a tiny fraction of Hari's countless supreme bliss and good qualities. If, while eating, forgetting oneself, one says 'Offered to Krishna', He takes it gladly, as a child holds out its hand to its mother at mealtime.",
        '0.26': "Hari, Lakshmi's Lord, never abandons the deeds that living beings do; He accepts them and always gives the results according to each one's qualification. Fire consumes everything yet undergoes no change; what wonder then that Hari, the purifier of purifiers, eats and is unchanged? Understand this.",
        '0.27': "To a stained tongue even good food and water at first seem poisonous; to a pure tongue every taste shows itself delicious at all times. To the beautiful-limbed Lord every taste is auspicious, and He is the Annamaya; would the one who drank the poisoned milk of Putana refuse (what is offered with devotion)?",
        '0.28': "What more is there to say? Vayu drank the Kalakuta poison and saved the world, and one of his servants came to be called \"immortal.\" The Lord of Lakshmi eats the whole mass of good and bad deeds, yet no gain or loss ever touches Him; so give up your own self-willed tastes.",
        '0.29': "Thus, remembering again and again Achyuta's forms and names in the various foods, keep on eating; knowing Him as the one who brings the objects, sustains them, controls and pervades them, remain unattached, offering your merit and sin at His feet.",
        '0.30': "Taking 5,89,705 forms (the 5,85,400 forms in the sheaths and the 4,305 in Vayu) and becoming the food for those who eat, Jagannatha Vitthala, Lord of Shri, Bhu and Durga, pervades the body from the feet to the head and protects it always.",
      },
    },
    'harikathamrutasara-05': {
      summary: "Sandhi 5 (Vibhuti, \"the manifestations of the Lord\"): Hari is present in images, the shaligrama stone, guests, the tulasi plant, sacred trees, teachers, the elements and the passing days, and He takes countless forms in each of them. The sandhi shows how to worship Him in these and in the body itself, which becomes His temple, sacrifice-pit, chariot and boat; it places Hari and the gods in the four classes of society, explains bimba and pratibimba (the original and its reflection), and ends by urging that every act be offered to Him.",
      verses: {
        '0.0': "With the grace of the guru, I will tell the essence of the nectar of Hari's stories; devout devotees of the Lord, listen to it with respect. (The refrain sung at the start of every sandhi.)",
        '0.1': "As you see here and there the supreme manifestations (vibhuti) of Lakshmi's Lord, think of them in your mind and look on them with wonder. Learn from the wise the different kinds: common and special, of the same class and of other classes, whole and partial.",
        '0.2': "The many beings He has created move about in this world; among them are those of the same class and of other classes, with common and special features. Knowing these, and placing His presence in each proper place, worship Him with a joyful mind and revel as you see the forms of the all-pervading Lord.",
        '0.3': "Places of His presence: an image, the shaligrama stone, the cow, a guest, the holy tulasi, the pipal tree, the renunciant, the forest-dweller, the householder, the student, the sacrificer, oneself and others, the earth, water, fire, wind, stars, sky, the nine planets, yoga, the senses, the lunar day, the bright and dark fortnights and the sun's transits.",
        '0.4': "Lakshmi's Lord dwells each day in the shaligrama, shining like a form set in fire-refined gold. In 5,535 forms He is ever within the presiding deities of the mountains.",
        '0.5': "In images of Sri Hari He is present in 513 forms, firmly established. As fire shows itself when wood is churned, He shows Himself, in the very form of each image, among the gods in those images to those who look with devotion.",
        '0.6': "As the controller of the instruments of worship, He takes 52,114 forms in the articles used. Those who know these forms and names and worship Him thus, He accepts their worship as a thirsty man takes water.",
        '0.7': "Know that Hari, the original (Bimba), dwells gladly in inert things like gold and in the gods, and in dharma, artha and kama. Without craving more, take the little food and coarse blanket the Lord of the universe-family gives each day as good fortune, and worship His feet.",
        '0.8': "In water He is present in 24 forms; in the tulasi leaf in 5,317 ('three and two' thousand, three hundred and seventeen); in flowers in 161; in the lamp in 13; and in sandal paste (gandha) in 403 good forms.",
        '0.9': "Established in the eight-petalled lotus of the good heart, supreme in glory, He moves through its petals and stays within. He fosters wrong-mindedness and wrong acts in the wicked, and good knowledge and dharma in the virtuous, ever faultless and full of bliss.",
        '0.10': "In wealth, body, house, wife, children and friends, in qualities, mind, intellect and senses, in knowledge and action, He is called by the name of each. Keep remembering that He always does everything according to His true will.",
        '0.11': "Contemplate with true devotion, never forgetting anywhere, these three kinds of things as His: feelings, materials and actions. To the devotees who thus serve Him daily as their own Lord, the merciful Protector gives Himself, as He favoured the elephant (Gajendra).",
        '0.12': "In the sky and the other elements, the things known as good aids to worship appear in ever-new variety for use in meditation. Thinking of them thus, always worship Govinda, behold Him, dance with joy and praise Him.",
        '0.13': "Fix the form of the lotus-navelled Lord in your mind with steady devotion, and do not complain daily of cold, heat, rain or wind. Offer the earth's fragrance as sweet scent, water as taste, form as the lamp, the wind as the fan, and sound as music; He is pleased.",
        '0.14': "Offer the body's organs as the Lord's own homes: daily cleansing is the washing and sweeping, the senses are the lamps, the meeting of the senses with their objects is the couch, the pleasure it gives the mattress, and surrender of the self the garment.",
        '0.15': "Offer sinful deeds as sandals under His feet, holy discourse on the scriptures as sandal paste, the mind's good states as tulasi and flowers, anger as the incense burnt, devotion as the ornament, the all-pervading good intellect as the umbrella, true knowledge as the lamp, and the recounting of His qualities as the waving of lights (arati).",
        '0.16': "Offer the mind, speech and body's circumambulation day after day to the all-pervading lotus-eyed Lord, and go on rejoicing. Bring it into your experience; among all means this is the chief. If told to ordinary men it is not understood, only by the wise.",
        '0.17': "To win the four goals of life there is no other means in all the fourteen worlds, as every scripture shows. For Lakshmi's Lord, who shines pervading the senses and their objects, complete surrender of everything is the great worship and the true means.",
        '0.18': "The inner sacrifice: the body is the fire-pit, the senses are the fire, the sense-objects that arrive are the fuel sticks, effort is the wind, desire the smoke, the Lord's nearness the flame, union the blaze, the overflowing joys the sparks, and every word spoken at the moment the mantras.",
        '0.19': "In the city of Madhu's foe (the body): the eyes and nostrils are the east gates, the mouth and the two ears the south and north gates, and the two lower openings the west gates. The six lotuses (centres in the body) are the mansion, the heart the pavilion, and the three qualities (gunas) the pots on its roof.",
        '0.20': "The body's constituents (dhatus) are the seven enclosing walls, the channels (nadis) the lanes, the passions the rutting elephants and their leaders, and the sushumna channel the royal road. The body hairs are the forests, and Vayu in his five forms is the sword that destroys the enemies called sins.",
        '0.21': "The sun, moon and others are the door-guards of Lakshmi's lord's palace, the modes of the mind are its foot-soldiers, and the sense-objects experienced are the wares that come to the city's market. The soul is the good merchant, and Hari Himself takes the toll.",
        '0.22': "In the palace of the mighty Lord, the ten senses are the rows of mirrors and the mind is the pavilion for the sport of Him who is free of all fault; the breaths that blow again and again are the fly-whisks, the intellect is the maid who waves them, and full prostrations to Damodara are His good couch.",
        '0.23': "For the house of Rama's Lord, the mouth is the great gate, the moustache and beard the arches hung over it, the hairs the flags; the walking feet, shanks, thighs, middle belly and veins form the house and its upper rooms, and the five sheaths are its corners.",
        '0.24': "This body is the chariot, its fragrances and sacred marks (tilaka) the banner, the mind the throne, the good intellect the finial, the good mind the rope, the three qualities the three staves, the two kinds of karma (good and bad) the wheels, and the ten senses the mighty horses.",
        '0.25': "Vayu is the charioteer of this body-chariot at all times, and Lakshmi's Lord is its master, the rider. Knowing this each day, one who lovingly nourishes the body with air, sunlight and the rest, yet gives up the sense of \"mine\" in it, is the great yogi.",
        '0.26': "Make the body a good boat on the ocean of worldly existence, the stream of karma, and sail with those who are His own. Think that Lakshmi's Lord plays through the days there; the Lord of Vayu will carry you across the ocean of samsara and give supreme happiness.",
        '0.27': "The things in the shop, men and women, the senses, and the oil and other materials put into lamps and fires: all are the gift of the Supreme Lord. Remembering this at every step without forgetting, move about everywhere fearlessly, joyous as a king.",
        '0.28': "Offer to Him in mind: Brahma's egg as the fine pavilion, Mount Meru as the throne, the Ganga as the bath, the directions as garments, words as mantras, the fruits, flowers and fragrance of trees, the wind, moon and sun as lamps, and the stars as ornaments. He accepts them and is gracious.",
        '0.29': "Among the Brahmins, Brahma is present, and with him Vasudeva. Among the Kshatriyas are Vayu, Garuda, Sadashiva, Shesha, the Sun, the Moon, Kama, Varuna and other gods, and they rejoice in seeing Sankarshana who dwells in them.",
        '0.30': "Among the Vaishyas are the vital airs (prana, apana, vyana, udana and the rest), the 49 Maruts, the Rudras and Vasus, Parvati, Kubera, Vishvaksena and other gods; one should lovingly contemplate Pradyumna as present in them.",
        '0.31': "Among those called Shudras are the Ashvins, Nirriti, Yama, Dharma, Yama's attendants, the Earth, Time, Death, Shani (Saturn) and others; Aniruddha, far from the ignorant, dwells in them. Know this and honour them.",
        '0.32': "Fearless Narayana, present in all four classes, does and makes each do the duties and good deeds of its class. He is woven through the inside and outside of all beings, and gladly gives them dharma, artha, kama and the rest.",
        '0.33': "Ordainer of death and wealth, with none equal or greater, worshipped in the Sama hymns and by the host of gods, dwelling in the three-peaked abode, of auspicious name: Madhumathana, Parashurama, Hayagriva. Think of Him in the form of the original (Bimba) as filling all things from end to end.",
        '0.34': "As one holds up a mirror and looks, one's own face appears with left and right reversed, yet pleasing to the eye; so to Aniruddha this world, being a created thing, appears as many separate things. Knowing it to be a reflection (pratibimba) of Hari the original (bimba), worship, and He accepts. (Pratibimba: the reflection, wholly dependent on its original.)",
        '0.35': "Those higher than oneself are called bimbas (originals) and those lower pratibimbas (reflections), and among all bimbas and pratibimbas Hari alone is the true Bimba. Singing this with joy and looking on, regard all eating, offering and giving as worship of the lotus-eyed Lord's feet, and dance in delight.",
        '0.36': "Like a river's water offered back to the river, do the duties He has given you, offering them to the Lord who rests on the ocean; be His instrument, not caught up in the mere rules and prohibitions, working like a ladle, and keep remembering Padmanabha in all your deeds.",
        '0.37': "Even when we do not know it, He lives within us and constantly enjoys the objects through our senses; but when they are offered to Him with knowledge, He gives the bliss of the self and protects us. The seasonal floods of rivers flow on whether people see them or not; yet only those who bathe in them and drink find comfort. (So the commentary explains the image.)",
        '0.38': "Whatever actions you do, offer them each day to Lakshmi's Lord with attentive devotion and without doubt. As a cow eats grass and water and then gives milk without a break, the Lord of honour accepts them and gives happiness afterwards.",
        '0.39': "In the circle of the directions (east, south, west, north), among Shiva, Agni, Vayu and the Moon, the One called Hamsa is present at all times, the emperor of the gods. By His own will He does not become visible to others, and so is called the Unmanifest Self (Avyaktatma).",
        '0.40': "In the years (Parivatsara, Samvatsara and the rest), Aniruddha and the other forms of the Lord are present as the Jupiter, solar and lunar years. Jagannatha Vithala, the mighty one, protects those who remember Him. Knowing this and the fitting means and one's own fitness, [worship accordingly].",
      },
    },
    'harikathamrutasara-06': {
      summary: "Sandhi 6 (Pancha-maha-yajna, \"the five great sacrifices\"): the sandhi teaches that life itself can be a sacrifice. In the five fires (mother, father, earth, water and sky; also the cloud, the earth, man and woman as in the Upanishadic fire-meditation) one offers the days, the senses and one's acts to Hari, who is present in each fire in many forms (thirty forms of Narayana, and numbered forms in the body's organs, the vital airs, the days and the seasons). It also shows Hari in the parts of the Sama chant, in the yugas, in the four classes, in the limbs of the body, in the elements and senses, and as the ten incarnations in the ten senses, and ends by offering everything to Krishna.",
      verses: {
        '0.0': "With the grace of the guru, I will tell the essence of the nectar of Hari's stories; devout devotees of the Lord, listen to it with respect. (The refrain sung at the start of every sandhi.)",
        '0.1': "In the five fires called mother, father, earth, water and sky, remember the actions and pervasion of Narayana's thirty forms, and keep offering the days as fuel sticks. Beg the Supreme, purifier of purifiers, for supreme happiness.",
        '0.2': "The sky as fire: the sun's rays are its smoke, the day its flame, the stars its sparks, the moon its embers. The wise think of the Lord's five forms in it, make words full of devotion their mantras, and offer oblations.",
        '0.3': "The rain-fire: Parjanya is the fuel, the clouds are the smoke, the lightning-flash the flame, thunder the sparks, and the thunderbolt the embers. Knowing the fire thus, the wise offer to Hari daily with supreme devotion.",
        '0.4': "The earth is the fire, the year the fuel, the sky the smoke, the darkness the flame, the directions the embers, the intermediate quarters the sparks. With the oblations called rain, please Hari and be a sacrificial priest within all, thinking of Him of every form.",
        '0.5': "The man as fire: speech is the fuel, the organs the flame, the tongue and the two ears the sparks, the eyes the embers. The food one eats daily is the offering to Krishna, the best of the Yadus; so offered, He accepts it daily and protects.",
        '0.6': "Know also the woman as fire: the organ of generation is the fuel, words that lead to desire are the smoke, the womb is the great flame, entry the embers, the passions the sparks; what is released is the offering to Purushottama. He accepts it and protects.",
        '0.7': "For those who, never forgetting these five fires, remember daily the twenty-five forms of the five-formed Lord, He does not let them reach another birth. The lotus-eyed Lord who protects His own kinsman in battle and gave a goal even to one who reviled Him, the remover of fear, is fond of His devotees.",
        '0.8': "Like the Pancha-nari-turaga (the horse formed of five women), the five-formed Lord takes thirty forms, each called by its own name. Through the mouths of the five fires He gives the five kinds of beings the body made of the three qualities and five elements, and sports there.",
        '0.9': "As Padmanabha, Achyuta and others in countless forms, Hari is the one Self in the hearts of all beings from Brahma and Shiva down. As Prana (life) He is in ten forms within the ten vital airs, at the levels of the elements (adhibhuta), the self (adhyatma) and the presiding gods (adhidaiva).",
        '0.10': "The wise should daily think of His 10,326 forms in the four seats (as the words 'two-five thousand' are read here; the Sankarshana Odeyar commentary reads 'two-two', 4,326), and of His 18,127 forms ('three-six thousand', one hundred and twenty-seven) in the ten vital airs, where He is called by the names of those airs.",
        '0.11': "Keep in mind that His good forms here number 28,453 in all, the full extent of His forms in the ten vital airs and the four seats (10,326 + 18,127). Knowing this, worship Purushottama everywhere and praise Him.",
        '0.12': "In the seats of sound and the other objects in all bodies, Hari is present in 16,416 forms. Vayu, in forms like Naga, presides over the third quality; and Hari, Durga's Lord, gives the senses knowledge and also wrong delusion. (The counts follow the verse's number-words.)",
        '0.13': "Within the five kinds of ignorance, in the seats of Naga and the other airs, Lakshmi's Lord takes five forms beginning with Kruddha and Ulka. He removes the ignorance of the good, gives the dark-minded ignorance and the like, and makes each practise according to their nature.",
        '0.14': "As Udgitha He is in cows; as Prastava and Hinkara in two forms in sheep and goats; as Pratihara in horses; as Nidhana, the life-giver, in men. Thus the five parts of the Sama chant are in them. For those who remember Him at every moment, He does not let them reach rebirth.",
        '0.15': "In the four yugas, Hari Himself is the promoter of each age's dharma and works, taking four forms beginning with Vasudeva. As the initiator of each age and establisher of dharma, He gives wealth to His devotees.",
        '0.16': "Narayana is in the head, Vasudeva from the neck through the trunk, Pradyumna on the right side, Aniruddha on the left, and Sankarshana in the lower limbs. Seeing thus the five-formed Lord in all bodies, rejoice.",
        '0.17': "Narayana is present in the whole body; Sankarshana from the waist to the feet; Vasudeva from the head to the hips; Aniruddha on the left and Pradyumna on the right. For those who meditate thus, would there be rules and prohibitions about ritual impurity?",
        '0.18': "Padmanabha is in the hands; Hrishikesha in the mouth; Shridhara in the nose; Vamana in the tongue; Trivikrama in the soft skin; Madhusudana in the eyes; and in the ears, as the hearing, He is called Vishnu.",
        '0.19': "Govinda and Madhava are in the mind, Narayana in the tattvas, and Keshava in the mahat-tattva and the unmanifest. The great souls who contemplate so many forms in the body are not mere humans on earth: by the strength of Hari's grace they are the equals of gods.",
        '0.20': "He is in the earth as Krishna, in water as Hari, in fire as Parashurama and Upendra, in the wind as Janardana, in the sky as Achyuta, in smell as Narahari, and in tastes He shines as Adhokshaja, being the taste itself.",
        '0.21': "In form He is Purushottama; in touch, Aniruddha who brings it; in sound, Pradyumna pervades; in the organ of generation Vasudeva is present; in the organ of excretion shines Sankarshana; and in the foot, as its firm support, Damodara shines.",
        '0.22': "Shripati pervades the twenty-four principles in forms such as Aniruddha. Circling round all beings' bodies like a creeper, He is called the satisfier of the ancestors, and is established there, of incomparable greatness, by ninety-six names.",
        '0.23': "In the twenty-four principles and in the gods who rule them, from Brahma down, He is spread in 1,152 forms to protect all living beings. For the Lord of the world there is no purpose of His own in this.",
        '0.24': "Lakshmi's Lord, with Lakshmi's power and others, is united in eleven forms with all the senses, called Purusha. In the fair, blissful, knowledge-formed body He is alone, never parting even for a moment, the supreme friend.",
        '0.25': "In sixteen forms He appears in the gross and subtle bodies and in the states of the self named Vishva, Taijasa, Prajna and Turya (waking, dream, deep sleep and the fourth beyond them). Taking fifteen forms, He abides in the ten senses, in the subtle elements, and in sky, fire, water and earth, under the name Atma.",
        '0.26': "Contemplate the Inner Self in the mind and the ego; the Supreme in the great and good principle (mahat); the Self of knowledge in the unmanifest. Always and everywhere worship, in all bodies, the fifty forms beginning with Aja, who is to be known through the fifty letters.",
        '0.27': "In the twenty-four principles and the gods who rule them, from Brahma down, He is spread in 13,800 forms; in twenty-four forms He is spread within all, and as the five-formed Lord He delights like an ordinary person.",
        '0.28': "The twelve fair forms beginning with Keshava are in the twelve months and in the twelve tilaka marks; Vedavyasa, Aniruddha and the other forms are in the six seasons. Knowing this, through the thirty days of a month do good works and dharma without expecting reward, pray for His mercy and praise Him.",
        '0.29': "In clods, gold, iron, stone, wood and all such inert things, and in all conscious beings from Brahma down, He makes them act each day without their knowing. Dear to all, He gives every wish and protects all living beings.",
        '0.30': "Vasudeva and Aniruddha are in the male body, and Sankarshana and Pradyumna in the female body. Those who worship Narayana, praised in the Veda passage of the two birds (dva suparna) and abode of all life, are called liberated while living.",
        '0.31': "In His own countless forms within Hiranyagarbha (Brahma) and others, the ocean of mercy Hari does and causes all their actions without Himself being troubled. He makes them blessed, accepts the meritorious deeds of all the gods, gives the fruits and protects.",
        '0.32': "The clouds in the sky can tell the waters of the different rivers apart even within the sea; can crows and sparrows know the state of a river's water? So too, this world bound by the three qualities lives within the Lord who lies on the serpent-couch: those learned in the scriptures understand it, but the ignorant cannot grasp it.",
        '0.33': "In the senses, the qualities and the elements, and in the gods like Brahma who rule them, remember His four forms each day everywhere; rejoice, dance and sing helplessly with love. To such singers He shows His presence, frees them from worldly existence and nourishes them.",
        '0.34': "The primal form is in the mind; in the pair of ears Matsya and Kurma; in the skin and tongue Varaha and Narasimha; in the nose the boy Vamana; in the mouth Parashurama; in the hand Rama, destroyer of Vali; and in the foot Krishna.",
        '0.35': "Buddha, who bewilders the Jinas, is in the organ of excretion, and Kalki, destroyer of demons, in the organ of generation. Knowing thus the ten forms in the ten senses, say \"Offered to Krishna\" over every experience; the remover of sorrow, Jagannatha Vithala, who pervades the universe, accepts it.",
      },
    },
    'harikathamrutasara-07': {
      summary: "Sandhi 7 (Pancha-tanmatra, \"the five subtle elements\"): the five elements (earth, water, fire, wind, sky) with their subtle forms (the tanmatras), the fifty-one letters, the body's channels, breaths and days are all seats of Hari, who is present in each in numbered forms and controls them. The sandhi gives the counts, shows how He is reflected in the minds of the good as an object in a mirror (bimba and pratibimba), recommends the Narasimha name-mantra, and ends by teaching that the Lord is utterly different from the souls and from inert matter, that even Lakshmi cannot reach the end of His qualities, and that all stand dependent on Him.",
      verses: {
        '0.0': "With the grace of the guru, I will tell the essence of the nectar of Hari's stories; devout devotees of the Lord, listen to it with respect. (The refrain sung at the start of every sandhi.)",
        '0.1': "The five elements, earth, water, fire, wind and sky, with their five subtle forms (tanmatras), and the Lord who is to be known through the fifty-one letters: He pervades this body, giving gods and demons happiness and sorrow without end, and plays; He afflicts those who hate Him.",
        '0.2': "Aniruddha, the Lord denoted by the Pranava (a-u-m), is present in the body in three names (Vishva, Taijasa and Prajna) in its three seats (eye, throat and heart, for waking, dream and sleep); He is also present in five, in twenty-one and in twenty-four forms, and controls the 72,000 channels. Like the sun with its rays entering darkness yet untouched by it, He shines everywhere in the world.",
        '0.3': "In the four seats of the body, the soul, the subtle body and the gross body among them, Hari is present as Vishva, Hayagriva, Mulesha and Achyuta, including the Hamsa forms. In these four seats one should contemplate Shanti's Lord in four forms, and in nineteen forms everywhere.",
        '0.4': "As in a clear mirror all objects are reflected and made visible, so Hari, the original (Bimba), though within inert and conscious beings, shines in many forms in the mind-mirror of good people; He is unmoving, free from ill, unchanging, needing no support, infinite.",
        '0.5': "In these four bodies, in the sheaths and the body's constituents, Hari, the Lord of Prana and Bharati's husband (Vayu), is present as the 21,600 breaths of a day, the form called Hamsa; abiding within the Sun and the Moon (who govern the in- and out-breath), He guides them by the hand and fills the whole egg of Brahma.",
        '0.6': "He shines as the Lord made of speech and mind (Vangmanomaya), whose form is the scripture: five heads (the four Vedas and the Mahabharata), ten arms (the ten Upanishads), two feet (the eighteen Puranas and the eighteen Upapuranas) and one belly (their whole meaning). Present daily in the senses, the body's constituents and the 72,000 channels, free of every fault, He is known as the One taught by the Mahabharata.",
        '0.7': "Praised in the Rig Veda, Lakshmi's Lord in the form called Vishnu takes forms in the body's waves (hunger, thirst and the rest) and in the elements; bearing the sixty-four arts, He dwells in Brahma, Shiva and the other chiefs and constantly sports in the world under the name Chatushpad (the four-footed).",
        '0.8': "In the four bodies of living beings from grass up to Brahma, the wise should count Narayana's forms: 5,126 as the Sankarshana Odeyar commentary reads 'saviradaidu' (five thousand), referring back to the 5,125 forms of sandhi 4; read plainly the words give 1,526. To those who daily repeat His names Ghrinih, Surya, Aditya, He gives health and wealth.",
        '0.9': "Know 574 forms in each of the Sun's rays at the elemental level (adhibhautika), in all its thousand rays ('five-two hundred', ten hundred); 121 forms at the level of the self (adhyatma), as Arka; and 231 forms at the divine level (adhidaiva), as Aditya: the learned meditate on them with reverence. (So the commentary and the Bemmatti edition count them.)",
        '0.10': "As the Moon (the bright, night-making one), Sankarshana and Pradyumna are within the Moon and Sun in 360 forms; He is called the Day-year (Ahas-samvatsara), by a special name. To those who know this He gives health and good fortune, the blissful one.",
        '0.11': "Lakshmi's Lord, present in the fifty-one letters, pervades all beings up to the unmanifest space; He brings forth the Vedas, grammar, the Mahabharata and the many shastras, Puranas and commentaries, and is called the one made of mind and speech.",
        '0.12': "The Bearer of the burden (Bharabhrit) fills the moving and unmoving everywhere in 1,624 forms: He shows His form in the twenty-four inert principles and in sixteen conscious beings, in every place.",
        '0.13': "Like a gem set on a gold ring, He shines in the minds of Brahma and the others; He both supports Brahma's egg and dwells within it as the one meditated upon. In the Moon He is present in 242 forms as the supporter, and in the crops (that the Moon nourishes) in 142 forms as the supported, never leaving them (some copies read 'in the hare-mark' for 'in the crops').",
        '0.14': "Knowing His 2,008 forms in all things, worship Shrivara, ask for boons and praise Him. What is the use of merely bathing in water and counting on the fingers in the sun? One who does not follow good teachers and elders does not know the secret.",
        '0.15': "Again, within the soul's own conscious body He is present for living beings in 80,725 forms as Narasimha. He is Death to the death that comes day and night; fond of His servants, destroyer of fear, endowed with every fortune.",
        '0.16': "In Jvara (the deity of fever) He is present in 27 forms and in Hara (Shiva) in 28; read together these give 2,827, the forms of the Narasimha named Jvarahara (remover of fever). By merely remembering Him, heaps of sin vanish, like frost at the sight of the sun's disc.",
        '0.17': "Without a break for a month, seated in a firm posture, with one-pointed mind and no deceit, chant steadily the auspicious name-mantra of Nrikesari (Narasimha). He destroys sins, fulfils wishes, and at the end gives the highest goal.",
        '0.18': "The four-formed Hari is in Brahma in thirty forms; in Vayu, as Pradyumna, in twenty-seven; in Brahma's sons in twenty-five and eighteen forms. Knowing these, worship the feet of the four-formed Lord through the hundred years of life.",
        '0.19': "A hundred years have 36,000 days, and the body has as many channels (nadis), in men and in women alike. Remembering the 72,000 forms of Hari, worship in all places the Supporter of all, knowing Him to be complete.",
        '0.20': "Himself the abode of time, karma, quality and nature, Lakshmi's beloved dwells within, called by the names of each form. In sport He protects, withdraws and creates all beings, making His house in the primal cause (prakriti), with its qualities and effects.",
        '0.21': "As lamps with oil and wicks burn, break the darkness of a house and show what is in it, so the lotus-eyed Lord, pleased with the devotion, knowledge and works of His own people, shines within their minds and shows them His qualities, forms and actions.",
        '0.22': "Whatever body He gives, whatever world He places one in, wherever one stays and whatever states may come, in this way contemplate the forms and qualities of the Lord of high and low in inert and conscious things; with good knowledge and devotion ask for His grace and praise Him.",
        '0.23': "In each thing the others are mingled as His forms; there is no room for mere guesswork about the forms of Indira's Lord thought of in this way. As a drop of water spreads through every thread of a cloth dipped in the ocean, so He pervades all the moving and unmoving.",
        '0.24': "Countless crores of Brahma's eggs are contained in one form of His, in one limb, in one hair, in one place. Did not Markandeya see creation and dissolution in one form of Lakshmi's Lord? What wonder is there in the Immeasurable One?",
        '0.25': "In one of His infinite forms are countless forms, and in one form are the worlds; in one and the same moment He does creation, maintenance and the rest without telling anyone, and abides pervading the world. Did the son of Nanda not show this to Arjuna, Indra's son, on the battlefield?",
        '0.26': "As in the \"nine-women elephant\" (a figure made of nine women), which appears as a single form while each limb is different, so the Lord's forms appear as one and, limb by limb, as different, giving different sights. In Brahma's egg, He is the changeless Cosmic Person (Virat).",
        '0.27': "In Brahma's egg the forms and qualities of Lakshmi-Narasimha are gathered like the waves of the sea: the causal parts that enter and pervade, and the effects, manifest and unmanifest. These are twenty-four manifestations (vibhuti), forms of the inner controller.",
        '0.28': "Like the thread running through a string of jewels, the Lord denoted by the Pranava (Om) plays daily within the world of conscious and inert things, full of bliss. He knows no weariness, is full of compassion, and abides among countless souls in a single-part form, controlling them.",
        '0.29': "Between soul and soul, inert and inert, soul and inert, inert and soul there are differences, and Shrivara (Hari) is utterly different and distinct from them all (the fivefold difference, pancha-bheda). Lakshmi too is distinct from the three throughout Brahma's egg; knowing that she is limited yet without an equal, worship these two.",
        '0.30': "The gods do not know His qualities; Sarasvati and others, called the presiding deities of the Vedas, can speak of Him but do not know them all. Even Brahma, who knows much, does not know His unfathomable qualities, which only Lakshmi can know. Know that Shridhara alone is the one to worship, Hari full of good qualities.",
        '0.31': "Unable to find the end of His countless qualities, Mahalakshmi becomes the ornaments, weapons, garments and dwellings of the Lord. Keeping His supreme, invincible greatness fixed in her mind and ceaselessly doing His errands, she attains complete dependence on Him.",
        '0.32': "As a boat on the ocean of the deluge, finding no shore, goes round and round, so Mahalakshmi, thinking of the lotus-eyed Lord's pure qualities and forms and finding no footing, becomes restless. What then can small souls grasp of His greatness in the three worlds?",
        '0.33': "Abode of Shri, Lord of the Satvatas, to be reached through knowledge, slayer of the demon Gaya, honoured by the families of sages, giver of honour, destroyer of his maternal uncle (Kamsa), wishing-tree to the humble, foe of Madhu, giver of life, Jagannatha Vithala: He protects those who trust daily that He alone is their refuge.",
      },
    },
    'harikathamrutasara-08': {
      summary: "Sandhi 8 (Matrika, \"the letters\" and their seats in the body): the sandhi walks through the body from the feet to the head, naming the limbs, the lotus-centres, the channels (nadis), the senses and the breaths, and the gods who preside over each, with Hari present within them as controller in numbered forms. It describes the three states of the self (waking, dream and deep sleep) with the forms called Vishva, Taijasa and Prajna, places the five parts of the Sama chant in the Lord's weapons, notes that even Lakshmi cannot reach the end of His qualities, and closes by teaching that one should see Hari in wealth, body, home and family and think \"I am His servant\".",
      verses: {
        '0.0': "With the grace of the guru, I will tell the essence of the nectar of Hari's stories; devout devotees of the Lord, listen to it with respect. (The refrain sung at the start of every sandhi.)",
        '0.1': "In Jayanta, deity of the feet, Hari named Sumedha dwells in the right foot; in its great toe Vayu is present in the form called Bharabhrit (bearer of the burden). In the joints of the legs, in ten forms named Tanki, Tara and so on (forms of the letters), He ever walks and makes the body walk, guarding it.",
        '0.2': "In the five joints of the right arm He is present as Kapila and the others (forms for the letters ka to nga), and in those of the left arm as Charvanga and the others (ca to nya), doing countless acts each day. Kind to the poor, He is in the sides, is called Parasuphali in the organs of excretion and generation, and dwells in the belly under names such as Vipula, Bali, Bhaga and Mana (forms for the remaining letters).",
        '0.3': "At the root of the navel are five lotuses of six petals each, and in them five forms named Aniruddha and the rest. They bring about birth for souls according to beginningless karma, nature and qualities, never deviating from the proper course, and carry out all the acts.",
        '0.4': "In the six-cornered figure at the navel, Shri Pradyumna, pearl-bright, is present within the future Brahma, served by the host of gods. Shining with the Kaustubha and other ornaments and weapons, He daily dries up the terrible Person of Sin.",
        '0.5': "In the middle of the belly, in the sushumna, is the orb of the twelve suns. There the five-formed Lord, in 360 forms, ever protects the gods who preside over the days and nights and destroys the demons.",
        '0.6': "In the heart is the eight-petalled lotus, and within it, called Pradesha (span-sized), He appears as the Original (Bimba), like the risen sun, adorned with lotus, discus, conch, mace, armlet, bracelet, crown, ring, pendant, the Kaustubha, necklace and neck-ornament.",
        '0.7': "In the throat shines a two-petalled lotus, where Mukhya Prana (Vayu) with his consort performs the worship of Hamsa (the breath). Giving room to water, food and the rest, the Lord named Udana speaks the word and makes all beings speak.",
        '0.8': "In the nose are the Ashvins (Nasatya and Dasra), and Prana the breath-deity, Bharati, Hamsa and Dhanvantari each in their place. The Moon and the Sun are lords of the two eyes, and within them Lakshmisha (in the Sun) and Dadhivamana (in the Moon) direct them.",
        '0.9': "In the right eye Pradyumna is present in the form of a post (stambha), and Lakshmi (Ambhrini), who bears His forms and qualities, is there in the form of a calf tied to it; served by Vayu, worthy of Brahma's office, by Shiva and all the gods, He makes all objects visible.",
        '0.10': "In the eyes dwell those named Vasishtha, Vishvamitra, Bharadvaja, Gautama, Atri and Jamadagni, and Indra, Surya, Dharitri (the Earth), Parjanya and other gods; daily, with supreme devotion, they worship the Lord of the three worlds.",
        '0.11': "In the light of the eye dwells Kapila, with Indra and the other regents of the directions; in the face of the right eye is Vishva, white and four-armed, called Nrigajasya, who lovingly gives beings the gross objects to enjoy and grants them the waking state.",
        '0.12': "The gods of the directions are established on both sides; in the ears dwell the gods who preside over holy waters, chief among them the river of the gods (Ganga); in the right ear dwells Trivikrama, father of the Ganga, who makes pure the people who contemplate Him thus.",
        '0.13': "In the mind are Kama and Indra; in the ego, Shiva; Garuda and Shesha preside over the intellect and consciousness, and established among them is Taijasa, the nineteen-mouthed one, who brings souls the dream state and is called the enjoyer of the subtle (pravivikta-bhuk).",
        '0.14': "Taijasa, the knowledge-formed, takes his seat in the heart and, called Prajna, grants the manifest joy of consciousness and gives their wishes to those who bow. Without any awareness He brings on deep sleep, and then again He Himself gives beings dream and waking.",
        '0.15': "In the tongue is Varuna, with the Fish (Matsya) form within him; in the small tongue (uvula) Indra, with Upendra within; in the palate the Sun named Parjanya, with Ardhagarbha within; in the place of speech the deity Subhamana, with Vamana within; in the forehead Shiva, with Keshava within; and in the cheeks Kama, Rati's lord, with Pradyumna there within him.",
        '0.16': "In the hair of the body is Vasanta (Spring), with Trikakuddhama within him; in the mouth Agni, with Bhargava (Parashurama) within; in the head the lotus-born Brahma, with Vasudeva within; in the mind (its presiding deity) with Vishnu within; and in the tuft of hair Maheshvara, with Narasimha within. That Lord removes untimely death for those who remember Him daily.",
        '0.17': "Vasudeva is in the crown in sixteen forms, and Himself the ruler in the face, eyes, ears and other limbs. Always at play and full of bliss, He hears and makes hear, sees and makes see, speaks and makes speak.",
        '0.18': "Of the 72,000 channels, the chief are one hundred and one, and in them are 101 forms of Hari. Knowing these to be the digits (kalas) of Hari called Kalasha (the vessel) in the body, the learned brahmins constantly worship Him with great reverence.",
        '0.19': "For this reason, in twelve of the channels, in the senses, are the holy rivers such as the Ganga; and Padmanabha, in the twelve forms beginning with Keshava, is there. In the tender sushumna He is the one Self.",
        '0.20': "Pradyumna, whom the Vedas expound, is in the body, in the sushumna, ida and pingala channels, in forms such as Vishva. Pure of soul, within Vani, Vayu and four-faced Brahma, He guides all souls according to their deeds and qualities, pervading everything.",
        '0.21': "Called by the good names of year, half-year, season, month and fortnight, Aniruddha, dark as a rain-cloud, and the others, five forms in all, pervade everything; the ocean of mercy, in forty-five forms (one for the year, two for the half-years, six for the seasons, twelve for the months and twenty-four for the fortnights), is attained by devotees who meditate on Him thus.",
        '0.22': "The five-formed Lord is present in twenty-five forms. The fifteen lunar days (of a fortnight), multiplied by the twenty-four fortnights of the year, come to three hundred and sixty ('six-five', that is thirty, read as three hundred, with sixty added): as many forms He takes as the days, each named after its day. For one whose mind is steeped in Him, where are the three afflictions and the great sins?",
        '0.23': "Present in the divisions of the day, the watch, the muhurta, the ghatika and the rest, He flows as Time, like the flow of the Ganga. Bhargavi (Lakshmi) bathes in the flood of His qualities, forms and actions, and is always full of bliss.",
        '0.24': "Lakshmi, the deity of the Vedas, pondering in her mind, cannot find the beginning, middle or end of the qualities, forms and actions of Hari, Bearer of the Earth; yet the ocean of mercy, Lord of the worlds, accepted her as His wife, as a king accepts a feast in a beggar's house.",
        '0.25': "The learned should reflect that all the good qualities found in Shridevi are present, by right reasoning and in order of rank, in lesser measure in all souls down to the blade of grass. Knowing that she is the consort of the God of gods and the mother of Brahma, yet never knows His end at any time, what then of mere men?",
        '0.26': "In milk, curds, butter and ghee, Shanti's Lord (Aniruddha) is present, named Saurabha-rasa, and is called by four names as knowledge, action and will power and the rest; and Bharati, Vagdevi (Sarasvati), Vayu and Brahma are established there at all times.",
        '0.27': "Eight Vasus, nine Prajapatis, forty-nine Maruts, eleven Adityas, as many Rudras, and two Ashvins: these gods, ninety in all (a hundred less ten), are controlled by the four-formed Lord, who dwells within Brahma, Vayu, Garuda and Shesha.",
        '0.28': "He appears as Hinkara in the discus, Pratihara in the conch, Nidhana in the mace, Prastava in the lotus, and the compassionate one as Udgitha: these are the five parts of the Sama chant. Remember and bear in mind these five forms of Rama's Lord in the conch, discus and other weapons.",
        '0.29': "The body is the chariot (its deity Brahma), and the goddess of speech is its ropes; Rohini and the Moon, in the ears, are the reins; the Sun and Samjna (in the eyes) are the horses; the fire-eyed Shiva is called the charioteer; and the Lord named Prana, denoted by the Pranava (Om), is the master who rides it.",
        '0.30': "His immeasurable greatness and boundless qualities cannot be contained by the Shruti and Smriti, which are made of limited letters, nor can the gods who preside over them, Brahma, Shiva, Indra and the rest, understand them daily. Only the all-knowing One knows the beginning, middle and end of His own greatness.",
        '0.31': "Know that Hari abides in wealth, body, house, wife, children, friends and the rest as the inner Self. Knowing this, one who daily gives satisfaction to the high, the low and the middling, and has done what is to be done, without becoming deluded, should think, \"I am His servant.\"",
        '0.32': "Without break, constantly contemplating, worshipping, seeing and delighting in the beautiful forms of the God of gods in all bodies: Shrivara Jagannatha Vithala, the purifier of the fallen multitude, being pleased, mercifully removes the pain of worldly existence.",
      },
    },
    'harikathamrutasara-09': {
      summary: "Sandhi 9 (Varna-prakriya, \"the process of the letters\", with their accents udatta and anudatta): Hari is the one denoted by the fifty-one letters, by the Vedic accents and by sandhi, visarga and bindu, and those who know and worship the names and forms in them speak the meaning of the Veda. The sandhi teaches that all deeds, bodily, local and temporal, are to be done without desire and offered to Him, that the soul is atomic and the Lord dwells with it in the heart-lotus, how the sphere of each god brings its own mood, the layout of the subtle channels and the body's constituents, and that the devotee who remembers the Lord's forms in the body is made a knower of Him directly (aparoksha).",
      verses: {
        '0.0': "With the grace of the guru, I will tell the essence of the nectar of Hari's stories; devout devotees of the Lord, listen to it with respect. (The refrain sung at the start of every sandhi.)",
        '0.1': "Hari Himself is the One denoted by the fifty-one letters and by the accents (udatta, anudatta, pracaya, svarita), and by sandhi, visarga and bindu. Those on earth who know and worship the names and forms He has in them are the equals of gods, not mere men, and what they speak is the meaning of the Veda. (Pracaya is the level, monotone accent.)",
        '0.2': "Knowledge of the Lord, true devotion to the Lord's servants, freedom from craving for sense-objects, and daily aversion toward the mithya-vadin (the one who speaks falsehood; in the author's Madhva sense, a teacher of the world's unreality). Knowing that Rama's Lord dwells in all these beings, fulfilling their wishes is the great sacrifice, the worship of Hari.",
        '0.3': "Called the One Self of the thirty gods, established in earth, water and fire, in the ten senses and their lords, in Prana (Vayu) and the Adityas, ever known and of limitless greatness, He, named Sankarshana (Nidhana), accepts all the objects of the senses.",
        '0.4': "Actions are of three kinds, relating to the body, the place and the time. Knowing which of them are prescribed, do them without desire, and, remembering in your mind the glorious form named Brihati of Bharati's Lord (Vayu), offer them each day to the Lord with supreme devotion.",
        '0.5': "Within the three kinds of action, as Krishna, Parashurama and Hayagriva, He is the inciter, taking nine forms. Himself unchanging, He acts and makes the wise, humans and demons act, and, as the true enjoyer, accepts and gives to the souls.",
        '0.6': "As one cooks food and offers it into the fire as a homa, so the Lord of the gods does and has done all actions. Knowing this, give daily with mind, speech and body, without doubt; the Remover of sorrow always accepts and satisfies His own.",
        '0.7': "Take the tip of a horse's tail-hair, divide it into a hundred parts, and divide one of those again into a hundred: so small is the soul. From Brahma and Shiva and all the gods down to a blade of grass, there is no greater or lesser size among souls; the soul is an atom. (In the Madhva view souls differ in quality, not in size.)",
        '0.8': "Hari dwells with the soul in forms of the size of the tip of the thumb, of the thumb, of a span, and in the soul's own shape. In such endless forms, pervading every part, the compassionate Lord protects these three worlds.",
        '0.9': "The Original (Bimba) is present with the thumb-sized soul in everyone, in subtle space, at the centre of the heart-lotus, as the wise say. The Self who sustains the universe, the knower (Prajna), the head of his devotees' family, protects the worshippers who can thus worship Him.",
        '0.10': "In all souls He is present as Purusha, in the shape of the soul's own body; as Hrishikesha, controller of the senses, in the senses; and as the all-pervading one named Turiya in the head, at the point twelve finger-breadths above, and in the 72,000 channels.",
        '0.11': "Pervading, Himself, the inside and outside of the soul and its body, and yet unstained, He acts in the deeds done by the soul. In the middle of the group, the lamp-hued, beautiful form shines in forms such as Vishva, accepting the service of Lakshmi, Brahma and Shiva.",
        '0.12': "By the Lord's grace Vayu too, like Hari, taking names such as Garuda, Shesha and Bhava (Rudra), controls the senses in the soul's own body; Brahma, Vani and Bharati, together with Bharata (Vayu), abide in the subtle body; the other gods have no place there.",
        '0.13': "By the Lord's will the subtle (linga) body encloses the soul as a husk encloses grain, with a gap around it, like a covering. The presiding deity of this wholly inert matter is called Mahalakshmi. It clings to the soul until the bath in the river Viraja (the boundary river at liberation).",
        '0.14': "Between the subtle body of sixteen parts and the Aniruddha body lie two coverings, the one that veils the soul (jivacchadika) and the one that veils the Lord from it (paramacchadika). Janardana keeps the demons far away so that they cannot enter, and abides within the three qualities; hence He is called Trivrit, the threefold.",
        '0.15': "For Rudra and the other gods the Aniruddha body is their home; dwelling there they do no work. From there, here in the gross body, the wrathful demons and the gods, vying with one another, carry out the opposed acts (good and bad) and their fruits, all at the command of Prana's Lord.",
        '0.16': "On earth, in holy places and sacred waters, in the cold, rainy and spring seasons, in the three kinds of dharmic action (of the body, the place and the time), Brahma and all the gods, bearing the qualities and following them, are present among all and carry out their work in those who act.",
        '0.17': "The sushumna, as fine as a hair divided into a thousand parts, runs through the middle of the body up to the end of the head. In this sushumna, in the west, north, east and south, are shining, lightning-like, adamantine radiances.",
        '0.18': "In that channel of the lotus-born (sushumna) is a triangular wheel; in the middle of its fire-orb is the one called Sankarshana. Burning up day by day the vile Person of Sin, the compassionate Lord brings the soul to Shri Vasudeva, who is full of knowledge.",
        '0.19': "In the middle of the central channel, at the root of the heart-lotus, Vayu dwells at the lotus-feet of the Root Lord (Mulesha); at Vayu's feet the soul abides, clothed with the subtle body and the Aniruddha body, and Kapardi (Shiva) and all the gods guard it.",
        '0.20': "In the middle of the stalk, in the eight-petalled heart-lotus, the Lord called Hamsa moves around like a potter's wheel. At all times He accepts the service of the guardians and, in mercy, fulfils their wishes.",
        '0.21': "As Vamana, Parashurama, Rama, Krishna, the Fish, Hayagriva, Kapila and Narasimha, satisfying each one, ever blissful, He dwells in the heart-lotus as the Original (Bimba).",
        '0.22': "On reaching Indra's realm the mind turns to the path of good merit; at Agni's house come sleep, laziness, hunger and thirst; at the house of the Sun's son (Yama), outbursts of anger show; in Nirriti's, sins are done, while He remains far from the ignorant.",
        '0.23': "In Varuna's sphere come jest and laughter, in Vayu's coming and going; in the realms of the Moon and Kubera a mind for dharma is born; in Shiva's house arises the thought of giving cows, wealth, land and daughters in marriage without hesitating for even a moment.",
        '0.24': "When the Root Lord leaves the petals and comes into the heart, around the pericarp, detachment arises; when He reaches the filaments, dream; at the edge of the pericarp, in the subtle body, deep sleep; and when Madhuha (Hari) comes to the pericarp itself, waking arises. Holding the eight weapons beginning with Sudarshana, He moves through the houses of the regents of the directions (the petals) and gives such dispositions.",
        '0.25': "While Vayu, called Sutra (the thread), expounded by the Gayatri, is present in the body, those who do not know it wander over the earth with sons and wives, wherever they see a holy place, and boast, \"We have made pilgrimages to holy places daily!\"",
        '0.26': "In the soul's own body He is Narasimha, called by the name Sharira; in the subtle body of sixteen parts He is called Purusha; in the Aniruddha body He shows Himself as Aniruddha, Shanti's Lord; and dwelling in the gross body as Pradyumna, He sets it in motion.",
        '0.27': "Skin, hide, flesh, blood, fat, marrow and bone are the seven constituents; in them dwell the forty-nine Maruts, seven in each. Called by the names of the seven parts of the Sama chant, Nidhana, Hinkara and the rest, the Lord is present in the constituents in forty-nine forms.",
        '0.28': "Outside the seven constituents, in the sheaths such as the food-sheath, unstained by them like fire in heated iron, He gives each its assigned experience. Called Taijasa, Prajna and Vishva, He gives dream, deep sleep and waking.",
        '0.29': "In the marrow in the body and at the joints of the fingers, in 360 places in three regions, the wise count 1,080 forms (three at each place). Rama's Lord plays there together with the gods in the body.",
        '0.30': "As the larva (kita), through devotion to the wasp (peshaskara), gives up its larval nature, takes the wasp's form and goes about like it, so small souls, by meditating with devotion on Hari, the foe of Kaitabha, quickly cross the forest of worldly existence and attain a form like His (sarupya).",
        '0.31': "For those devotees who, in this body, remember the Lord's forms at every step with devotion and without forgetting, Jagannatha Vithala, Lord of the cows, ever draws near and makes them knowers of Him by direct realization (aparoksha), and protects them at all times.",
      },
    },
    'harikathamrutasara-10': {
      summary: "Sandhi 10 (Sarva-pratika, \"all things as symbols of the Lord\"): for one who knows Hari as present in everything, every place is holy, every time a festival, every being worthy of gifts, every word a mantra and every act worship; the planets and gods are favourable to His servants, and even the demons' controllers act only by His command. The sandhi warns that bathing, pilgrimage, ascetic dress, recitation and fasting are empty for the one who says \"I and mine\" and does not remember Hari. The poet says he speaks as the Lord speaks in his heart, asks that the secret be told only to devoted listeners, and ends with a hymn of victory to the Lord's incarnations.",
      verses: {
        '0.0': "With the grace of the guru, I will tell the essence of the nectar of Hari's stories; devout devotees of the Lord, listen to it with respect. (The refrain sung at the start of every sandhi.)",
        '0.1': "Brahma, Shiva and the other gods, even the highest, are themselves called bound souls, and the Supreme Brahman is another. To those who serve the feet of Hari daily they are favourable; can they ruin them? Do the servants of Lakshmi's beloved ever suffer defeat?",
        '0.2': "For those who lovingly praise the lotus-feet of Shridana (Hari), the nine planets act as if placed in the eleventh house, the most favourable. The Adityas (gods) constantly remove their ills of mind and body and protect them, all acting together by the Lord's command.",
        '0.3': "To the yogi who knows this, all the water in cow-hoof prints on earth is holy water, trees, mountains and the very ground are holy fields, the multitude of beings are images of Shri's Lord, the food they give is the offering, and every step along the road is a dance.",
        '0.4': "For one who meditates on the pure form of the Lord whom Shiva worships, every place is a holy place, every time a festival time, every person in the three worlds is worthy to receive gifts, every word is a mantra, and every task is worship.",
        '0.5': "The deities presiding over sacred ponds, tanks, wells and lakes fill the pores of the body's hair; and think of the Ganga and the other rivers as flowing within the 72,000 channels.",
        '0.6': "Madhava, the inner controller of Vayu, plays each day in the three crore and more hair-pores and the 72,000 channels. The learned who know this are themselves the gods, their bodies are holy fields, and worshipping them is worshipping Hari.",
        '0.7': "Those on earth who know that bathing is an abhisheka for Shrivara find that the Ganga and other holy waters come and abide in the water they bathe in. What fruit have souls who do not know these meanings, even if they reach the celestial river?",
        '0.8': "He plays in the streams and rivers that flow on earth to the sea, without showing Himself as such. The wise follow the rules and prohibitions, but when contemplation of the Lord's form everywhere comes, they let go of all actions.",
        '0.9': "Brahma, Shiva and other gods, by Hari's command, are the inner controllers within Kali and all the other demons, who do their sinful deeds. Those firm in devotion and full of knowledge, offering everything to the Lotus-eyed Lord, are happy even among them.",
        '0.10': "In whatever souls they dwell, whatever acts they do and whatever forms and qualities they worship, can sinful acts ever touch the gods who are highly honoured by the Protector (Hari) and move about, in any world, by His strength?",
        '0.11': "A wife whose mind accords with her husband's, who delights in him each day and bears sons, is called one of conquered senses. Likewise, can other faults touch the great souls who delight in the nectar-feast of the Lord's stories, the servants of Achyuta?",
        '0.12': "As one who, to show his strength, swims against the current of a river in flood, and, his arms failing, sinks, so the man who forsakes Hari, abandons what the Lord of all has ordained from the beginning, and out of desire worships others, comes to grief.",
        '0.13': "The dull-minded man who says \"I\" and \"mine\", doing his daily bathing, japa, worship and other rites: the demons wash them off and carry them away, and Srinivasa does not accept them. It is as when a rutting elephant eats a ripe wood-apple fruit.",
        '0.14': "What use is it to wander through all the holy places on earth? What fruit comes from giving gifts without knowing the worthy from the unworthy? What use is reciting mantras and hymns with a pure body, for one who does not know that Hari is all-pervading and calls himself the doer?",
        '0.15': "What fruit comes from bathing in any water one sees and punishing the body? What fruit from carrying a staff and a water-pot and being called a renunciant? The man who does not fix his mind day and night on the lotus feet of the Lord of the bird-born (Garuda's Lord), like a bee, finds no happiness.",
        '0.16': "What use is it to recite the Vedas, shastras and Puranas, to abandon all forbidden acts and do good deeds, to fast and hold the breath, if desire and anger have not ended and the man still says \"I\" and \"mine\"?",
        '0.17': "What use is hearing, seeing, reading, speaking, singing or doing, day after day, for one who does not lovingly remember, each in its proper place, the birth, deeds, form and name of Srinivasa?",
        '0.18': "This is not pure poetry born of the power of my intellect and learning, nor am I a man who has learned the true methods of the principles from the wise. Madhva's Beloved is Himself in my heart, and I have spoken as He spoke; so the wise should lend an ear without looking at the faults of my verses.",
        '0.19': "As the sweetness in sugarcane, the nectar of Hari's deeds is not for one who forgets himself in the haze of fortune and youth. It is obtained only by one who, filled with the juice of devotion that overflows at Hari's lotus feet, plays in the ocean of happiness.",
        '0.20': "To people who do not know the varieties of devotion to the feet of Garuda-bannered Hari, this always looks like a riddle. To the Bhagavatas who praise the pure qualities of the Lord beyond the three gunas, He gives devotion and knowledge in abundance, and happiness, and protects them.",
        '0.21': "Brahmins should listen to this secret of the Supreme Principle with attention. Do not tell it to the harsh, the foolish, the self-styled scholars, the wicked or the tasteless; always tell it with joy to those who are the bees at the lotus feet of the Lord.",
        '0.22': "This is not worldly talk; would one listen to the word of the One Lord of the other world? Can it suit people of narrow mind? Can the water-dwelling frog know the lotus's fragrance as the bee accepts it? Its savour belongs only to the devotees of Hari.",
        '0.23': "(Addressing the Lord:) You have no purpose of Your own, You give all that is wished for, are full of all qualities, knowable, free from old age, death and sorrow, supremely wise, the Self of the universe, merciful, shining like the sun, of infinite glory; Your lotus feet are worshipped through the symbols (pratikas) such as ghee, O King of the gods!",
        '0.24': "Victory to the bearer of the mountain; victory to the Man-lion; victory to Vamana-Trivikrama; victory to Bhrigurama (Parashurama) and to the Infinite; victory to Janaki's beloved (Rama); victory to Rukmini's wish-fulfiller (Krishna); victory to the Buddha who bewilders the Jinas; victory to Kalki, destroyer of Kali; victory, victory to Rama's Lord.",
        '0.25': "Sat-chit-ananda Self, whose lotus feet are worshipped by Brahma and the gods, supremely auspicious, established in the heart of Madhva: Achyuta Jagannatha Vithala does not abandon the people who ever please Him. He swallowed the forest fire and protected the cows and cowherds in the forest.",
      },
    },
  },
};
